package plates.ui

import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.drop
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.merge
import plates.core.input.PlateController
import plates.core.input.PlateInputSource
import plates.core.input.PlateMode
import plates.core.input.SlotBehavior
import plates.core.input.resolveSlotBehavior
import plates.core.theme.PlateTheme
import plates.core.timing.PlateAnimationController
import plates.core.timing.PlatePartId
import plates.core.timing.Size
import plates.core.timing.Tween
import plates.core.timing.lerpSize
import plates.core.values.PlateCountry
import plates.core.values.PlateSpec
import plates.core.values.Rect
import plates.render.DisplayOp
import plates.render.Frames
import plates.render.LIVERY_MS
import plates.render.StaggeredText
import plates.render.lerpTheme
import plates.render.plateTheme
import plates.render.renderLayers
import plates.render.settledFrames

/** Where the UI places a native input over the painted plate [D2]; [box] is in spec units. */
data class SlotInput(val index: Int, val behavior: SlotBehavior, val box: Rect)

/**
 * [D1][D7] The headless half of the web plate: core state in, a layered [picture] out.
 *
 * State lives in [controller] (a host's, or one made here). The canvas owns the plate's canvas-level motion — the
 * livery fade and the box resize as [Tween]s, a resolved label's stagger, the part cues through a [PartClock] — and
 * reads them all at one frame time. A host paints through a retained surface (webMain's `PlateSurface`), repaints on
 * [wakes] and keeps repainting once per frame while [animating]; [svg] is a one-shot string.
 */
class PlateCanvas(
    spec: PlateSpec<*>,
    controller: PlateController? = null,
    values: List<String?>? = null,
    var theme: PlateTheme? = null,
    var country: PlateCountry? = null,
    var mode: PlateMode = PlateMode.display,
    var inputSource: PlateInputSource = PlateInputSource.system,
    /** Fixed part frames (H11); when null, [animation] drives them through a [PartClock]. */
    var frames: Frames? = null,
    private val animation: PlateAnimationController? = null,
    private val now: () -> Double = { 0.0 },
    /** The slot being edited, whose underline lights. */
    var activeIndex: Int? = null,
    /** A leaving ghost: the box to draw into, owned by the plate that replaces it; its own frame stretches to it. */
    var viewSize: (() -> Size)? = null,
) {
    /** Prefixes this canvas's SVG ids, so several canvases can share a page (see [opsToSvg]). */
    val id = "pc${nextUid++}-"
    val controller = controller ?: PlateController(spec, values)

    private val clock = animation?.let { PartClock(it, now) }
    private var livery: Tween<PlateTheme>? = null
    private var box: Tween<Size>? = null
    private val labels = HashMap<Int, StaggeredText>()
    private val livery6 = { t: PlateTheme -> listOf(t.plateBackground, t.plateBorder, t.ink, t.dividerColor, t.activeColor, t.inactiveColor) }

    val spec get() = controller.spec

    val values get() = controller.values

    fun setValues(values: List<String?>) = controller.setValues(values)

    /**
     * Everything that should make a host repaint: a value, the rejection or the hints, the animation style, and
     * every part's cue (so `introduce` and `comeInAll` wake it, which the controller alone never would).
     */
    val wakes: Flow<Unit>
        get() = merge(
            this.controller.changes.drop(1).map {},
            this.controller.rejection.drop(1).map {},
            this.controller.hints.drop(1).map {},
            *listOfNotNull(animation?.styleState?.drop(1)?.map {}).toTypedArray(),
            *(animation?.let { a -> PlatePartId.allOf(spec).map { a.cueOf(it).drop(1).map {} } } ?: emptyList()).toTypedArray(),
        )

    private val specSize get() = spec.canvasWidth to spec.canvasHeight

    /**
     * The face starts as [start] and fades to its own colours over [ms], from now; call before the first paint.
     * With [size] the box also grows or shrinks from it to the spec's size over the same [ms] (ease in-out), the
     * face laid out at the size it has at each frame.
     */
    fun morphFrom(start: PlateTheme, ms: Double, size: Size? = null) {
        if (clock == null) return
        val t = now()
        livery = Tween(start, plateTheme(spec, theme, values), t, ms, ::lerpTheme)
        box = if (size != null && ms > 0) Tween(size, specSize, t, ms, ::lerpSize) else null
    }

    /** The box the plate is drawn into at [t]: the spec's size, or the tween toward it. */
    fun size(t: Double = now()): Size {
        viewSize?.let { return it() }
        return box?.takeIf { it.running(t) }?.valueAt(t) ?: specSize
    }

    /** [H15] The resolved theme at [t]: a change of livery fades from where the last one had got to. */
    fun resolvedTheme(t: Double = now()): PlateTheme {
        val target = plateTheme(spec, theme, values)
        if (clock == null) return target
        val tw = livery
        val next = when {
            tw == null -> Tween.settled(target, ::lerpTheme)
            livery6(tw.to) != livery6(target) -> tw.retarget(target, t, if (spec.resolveTheme != null) LIVERY_MS else 0.0)
            // Same colours, other fields (ratios, alert): follow them without restarting the fade.
            else -> tw.follow(target)
        }
        livery = next
        return next.valueAt(t)
    }

    private fun labelText(i: Int, value: String, t: Double): Pair<String, List<Double>?> =
        if (clock == null) value to null else labels.getOrPut(i) { StaggeredText(value) }.frame(value, t)

    /** The plate at one frame time: every motion read at [t]. */
    fun picture(t: Double = now()): PlatePicture {
        clock?.observe(PlatePartId.allOf(spec), t)
        val size = size(t)
        val layers = renderLayers(
            spec, values, theme, country ?: spec.country, frames ?: clock?.frames(t) ?: settledFrames(), mode, inputSource,
            controller.isCompleted, controller.rejection.value,
            hintAt = { controller.hintAt(it) }, activeIndex = activeIndex, resolvedTheme = resolvedTheme(t),
            labelText = { i, v -> labelText(i, v, t) }, size = size, frameSize = if (viewSize != null) specSize else null,
        )
        return PlatePicture(size, layers)
    }

    /** The picture as one display list, bottom layer first. */
    fun displayList(t: Double = now()): List<DisplayOp> = picture(t).layers.flatten()

    /** True while something still moves at [t]: a part, the livery, the box, a label. A ghost moves until dropped. */
    fun isAnimatingAt(t: Double): Boolean =
        viewSize != null || clock?.runningAt(t) == true || livery?.running(t) == true || box?.running(t) == true || labels.values.any { it.running }

    val animating get() = isAnimatingAt(now())

    /** In input mode, the slots the display list leaves for native inputs. */
    fun slotInputs(): List<SlotInput> {
        if (mode != PlateMode.input) return emptyList()
        return spec.slots.mapIndexedNotNull { i, s ->
            val behavior = resolveSlotBehavior(mode, s.alphabet.input, inputSource)
            if (behavior == SlotBehavior.glyph) null else SlotInput(i, behavior, s.box.rect)
        }
    }

    /** A one-shot standalone SVG of the plate now; a live page paints through a retained surface instead. */
    fun svg(resolveAsset: (String, String) -> String = { p, a -> "packages/$p/$a" }): String = pictureSvg(picture(), id, resolveAsset)
}

private var nextUid = 0
